<template>
  <Teleport to="body">
    <dialog ref="dialog" class="museum-exhibition-dialog gallery-dialog-veil" :class="{'is-dark':dark,'is-closing':closing}" :style="viewportStyle" aria-labelledby="museum-exhibition-title" @cancel.prevent.stop="leave()" @keydown.stop>
      <header class="exhibition-detail-head">
        <span><GalleryMark/>On view</span>
        <button ref="close" type="button" class="exhibition-detail-close" aria-label="Close exhibition details" @click="leave()"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15"/></svg></button>
      </header>
      <div class="exhibition-detail-layout">
        <section class="exhibition-detail-copy">
          <h2 id="museum-exhibition-title"><ExhibitionTitle :text="view.title"/></h2>
          <MuseumQuestion v-if="view.question" class="exhibition-detail-question" :text="view.question"/>
          <div class="exhibition-detail-introduction" :aria-busy="loading">
            <p v-for="(paragraph,index) in introduction" :key="index">{{paragraph}}</p>
            <p v-if="loading && !introduction.length" class="exhibition-detail-status" role="status">Opening the introduction…</p>
            <div v-else-if="error" class="exhibition-detail-status" role="status"><p>The introduction is temporarily unavailable.</p><button type="button" @click="loadDetails">Try again</button></div>
          </div>
          <button type="button" class="exhibition-detail-enter" @click="leave('enter')"><span>{{state.kind==='complete'?'Visit again':state.kind==='started'?'Continue your visit':'Enter exhibition'}}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></button>
        </section>
        <figure class="exhibition-detail-ticket">
          <ExhibitionTicketFace :title="view.title" :image="image" :date="date" :number="number" :state="state" aria-hidden="true"/>
        </figure>
      </div>
    </dialog>
  </Teleport>
</template>

<script>
import GalleryMark from './GalleryMark.vue';
import ExhibitionTitle from './ExhibitionTitle.vue';
import ExhibitionTicketFace from './ExhibitionTicketFace.vue';
import MuseumQuestion from './MuseumQuestion.vue';
import { cachedExhibitionPreview, loadExhibitionPreview } from '../../utils/exhibitionPreview';
import { exhibitionTicketNumber, exhibitionTicketState } from '../../utils/exhibitionTicket';
import { museumSession } from '../../utils/viewMuseumSession';
import { lockBodyScroll } from '../../utils/bodyScrollLock';
import { initDialogBackdrop } from '../../utils/dialogBackdrop';
import { animateGalleryDialog } from '../../utils/galleryDialogMotion';

export default {
  components:{GalleryMark,ExhibitionTitle,ExhibitionTicketFace,MuseumQuestion},
  props:{view:{type:Object,required:true},dark:Boolean},
  emits:['close','enter'],
  data(){return {snapshot:cachedExhibitionPreview(this.view.id),loading:false,error:false,closing:false,session:museumSession(),viewportStyle:{}};},
  computed:{
    introduction(){return (this.view.dek||this.snapshot?.view?.dek||'').split(/\n\s*\n/).filter(Boolean);},
    image(){const art=this.view.illustration||this.snapshot?.view?.illustration;return typeof art==='string'?art:art?.src||'';},
    date(){const value=this.view.created_at||this.snapshot?.created_at,date=new Date(value);return !value||Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(date);},
    state(){return exhibitionTicketState(this.view.id,this.session);},
    number(){return exhibitionTicketNumber(this.view.id);},
  },
  mounted(){
    this.syncViewport();this._viewport=window.visualViewport;
    this._viewport?.addEventListener('resize',this.syncViewport);this._viewport?.addEventListener('scroll',this.syncViewport);window.addEventListener('resize',this.syncViewport);
    this._trigger=document.activeElement;this._releaseScroll=lockBodyScroll();
    this.$refs.dialog.showModal();this._motion=animateGalleryDialog(this.$refs.dialog,true);
    this._stopBackdrop=initDialogBackdrop(this.$refs.dialog,()=>this.leave());
    this.$refs.close.focus({preventScroll:true});this.loadDetails();
  },
  beforeUnmount(){
    this._destroyed=true;this._motion?.cancel();this._stopBackdrop?.();
    this._viewport?.removeEventListener('resize',this.syncViewport);this._viewport?.removeEventListener('scroll',this.syncViewport);window.removeEventListener('resize',this.syncViewport);
    this.$refs.dialog?.close();this._releaseScroll?.();
    if(this._trigger?.isConnected)this._trigger.focus({preventScroll:true});
  },
  methods:{
    syncViewport(){const v=window.visualViewport,w=v?.width||innerWidth,h=v?.height||innerHeight;this.viewportStyle={'--dialog-centre-x':`${(v?.offsetLeft||0)+w/2}px`,'--dialog-centre-y':`${(v?.offsetTop||0)+h/2}px`,'--dialog-height':`${h}px`,'--dialog-width':`${w}px`};},
    async loadDetails(){
      if(this.view.dek||this.loading)return;
      this.loading=true;this.error=false;
      try{const snapshot=await loadExhibitionPreview(this.view.id);if(!this._destroyed)this.snapshot=snapshot;}
      catch{if(!this._destroyed)this.error=true;}
      finally{if(!this._destroyed)this.loading=false;}
    },
    async leave(event='close'){
      if(this.closing)return;this.closing=true;
      this._motion=animateGalleryDialog(this.$refs.dialog,false,this._motion);
      await this._motion?.finished.catch(()=>{});
      if(!this._destroyed)this.$emit(event);
    },
  },
};
</script>

