.museum-exhibition-dialog.is-dark{--ex-paper:#292623;--ex-ink:#e7e2da;--ex-muted:#bdb6ac;--ex-border:#5c554e;--ex-accent:#c5ad84;color-scheme:dark;box-shadow:0 18px 60px #0005}
.exhibition-detail-head{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:30px;color:var(--ex-muted)}
.exhibition-detail-head>span{display:flex;align-items:center;gap:9px;font-size:13px}
.exhibition-detail-head .gallery-mark{width:18px;height:21px}
