.exhibition-detail-introduction{margin-top:24px;font:18px/1.65 'Quattrocento Sans',sans-serif;color:var(--ex-ink);text-wrap:pretty}
.exhibition-detail-introduction p{margin:0;font:inherit;color:inherit}
.exhibition-detail-introduction p+p{margin-top:14px}
.exhibition-detail-introduction .exhibition-detail-status{color:var(--ex-muted);font-size:14px;min-height:100px}
.exhibition-detail-status button{padding:8px 0;text-decoration:underline;text-underline-offset:4px}
.museum-exhibition-dialog .exhibition-detail-enter{display:flex;align-items:center;justify-content:space-between;gap:34px;min-height:44px;margin:26px 0 0;padding:9px 0;border-bottom:1px solid var(--ex-border);font-size:16px}
.exhibition-detail-enter svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.2;stroke-linecap:round;stroke-linejoin:round;transition:transform 180ms ease}
