@media(max-height:550px) and (min-width:681px){.museum-exhibition-dialog{padding:20px 28px 26px}.exhibition-detail-head{margin-bottom:16px}.exhibition-detail-layout{gap:30px}.exhibition-detail-copy h2{font-size:29px}.exhibition-detail-introduction{font-size:15px}.exhibition-detail-question{font-size:17px;margin:16px 0}}
@media(prefers-reduced-motion:reduce){.exhibition-detail-close,.exhibition-detail-enter svg{transition:none}}
</style>
